// Modelos em branco para "Novo documento" (gerados com docx, exceljs e pptxgenjs: A4/Calibri,
// uma folha vazia, um diapositivo 16:9 vazio). Em base64 para irem dentro da função.

export type BlankKind = 'docx' | 'xlsx' | 'pptx';

const BASE64: Record<BlankKind, string> = {
  docx: '',
  xlsx: '',
  pptx: '',
};

export const BLANK_MIME: Record<BlankKind, string> = {
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
};

export const isBlankKind = (value: unknown): value is BlankKind =>
  value === 'docx' || value === 'xlsx' || value === 'pptx';

/** Bytes do modelo em branco. */
export const blankFile = (kind: BlankKind): Uint8Array =>
  Uint8Array.from(atob(BASE64[kind]), ch => ch.charCodeAt(0));
